import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse(`{"title":"Little's Law","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/estimation/littles-law.md","filePath":"system-design/estimation/littles-law.md","lastUpdated":1788475713000}`),m={name:"system-design/estimation/littles-law.md"};function l(p,a,i,r,o,c){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="little-s-law" tabindex="-1">Little&#39;s Law <a class="header-anchor" href="#little-s-law" aria-label="Permalink to &quot;Little&#39;s Law&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Little&#39;s Law</strong> (John D.C. Little, 1961, MIT Sloan) 是排队论中最常用、最被广泛引用的定理:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mi>λ</mi><mi>W</mi></mrow><annotation encoding="application/x-tex">L = \\lambda W </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">λW</span></span></span></span></span></p><ul><li><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span></strong> = 系统中平均实体数 (concurrent occupations, queue + service)</li><li><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi></mrow><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span></strong> = 到达率 (arrival rate, 实体/unit time)</li><li><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>W</mi></mrow><annotation encoding="application/x-tex">W</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span></span></span></span></strong> = 平均逗留时间 (实体在系统中停留的总时间)</li></ul><p>它跨<strong>任意</strong>到达分布 + <strong>任意</strong>服务分布 + <strong>任意</strong>队列情形都成立. 是 back-of-envelope 估算 threadpool size、queue depth、worker count 的 first principle. 本章推导公式、应用例 (限流器、池容量、API P99)、与经典 counter-example (non-stable 系统如何破坏 validity)、Little&#39;s Law 在工业 ops 的应用 (SRE pool sizing)。</p><hr><h2 id="一、直觉与形式化" tabindex="-1">一、直觉与形式化 <a class="header-anchor" href="#一、直觉与形式化" aria-label="Permalink to &quot;一、直觉与形式化&quot;">​</a></h2><h3 id="直觉" tabindex="-1">直觉 <a class="header-anchor" href="#直觉" aria-label="Permalink to &quot;直觉&quot;">​</a></h3><p>如果:</p><ul><li>1 秒 来 1 个 客人 (λ=1/s)</li><li>每个客人在店里待 5 秒 (W=5s)</li><li>那么店里 &quot;steady state&quot; 平均同时有 1×5=5 个客人 (L=5)</li></ul><p>或说: 每秒进来 1 个客人, 每个客人占用 5 个细秒-slot (resource), 总 steady state 占用是 5 个 slots = 5 同时客人.</p><h3 id="形式化" tabindex="-1">形式化 <a class="header-anchor" href="#形式化" aria-label="Permalink to &quot;形式化&quot;">​</a></h3><p>证明 (simplified version, stable M/M/1):</p><p>设稳态到达率 λ, 服务率 μ (μ&gt;λ 稳定). Little&#39;s Law 在任意 markov chain stationary distribution 中 apply. 完整 proof 需要 ergodic average argument.</p><h3 id="三变量-推论" tabindex="-1">三变量 + 推论 <a class="header-anchor" href="#三变量-推论" aria-label="Permalink to &quot;三变量 + 推论&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>稳态关系</th></tr></thead><tbody><tr><td>未来到达 rate λ 与系统稳定性 要求 λ &lt; μ (μ 是服务率)</td><td>stability condition</td></tr><tr><td>L = λ × W</td><td>Little&#39;s Law</td></tr><tr><td>若 system is FIFO 单 server: 等待时间 W_q = L_q / λ (queue 内 L_q, 等 average time in queue only)</td><td>同公式</td></tr><tr><td>Conflict ratio ρ = λ/μ</td><td>单 server 利用率</td></tr><tr><td>ρ → 1 ⇒ L → ∞ (queue 长度→∞, latency→∞)</td><td>&quot;Bottleneck saturation&quot;</td></tr></tbody></table><hr><h2 id="二、工业应用例" tabindex="-1">二、工业应用例 <a class="header-anchor" href="#二、工业应用例" aria-label="Permalink to &quot;二、工业应用例&quot;">​</a></h2><h3 id="例-1-thread-pool-sizing" tabindex="-1">例 1: Thread Pool Sizing <a class="header-anchor" href="#例-1-thread-pool-sizing" aria-label="Permalink to &quot;例 1: Thread Pool Sizing&quot;">​</a></h3><p>API server 突发到达: λ = 1000 req/s, 平均 per-request 服务时间 W = 50ms.</p><p>应用 Little&#39;s Law:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mn>1000</mn><mtext>req/s</mtext><mo>×</mo><mn>0.050</mn><mtext>s</mtext><mo>=</mo><mn>50</mn><mtext>reqs concurrent</mtext></mrow><annotation encoding="application/x-tex">L = 1000 \\text{req/s} × 0.050 \\text{s} = 50 \\text{reqs concurrent} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1000</span><span class="mord text"><span class="mord">req/s</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0.050</span><span class="mord text"><span class="mord">s</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">50</span><span class="mord text"><span class="mord">reqs concurrent</span></span></span></span></span></span></p><p>需要 ≥ 50 工作线程(每 worker 一次处理 1 个 request). 否则 queue 涨 ⇒ W 涨 ⇒ P99 latency 涨.</p><h3 id="例-2-database-connection-pool" tabindex="-1">例 2: Database Connection Pool <a class="header-anchor" href="#例-2-database-connection-pool" aria-label="Permalink to &quot;例 2: Database Connection Pool&quot;">​</a></h3><p>PostgreSQL 平均 query 5ms, 突发 30K queries/s:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mn>30</mn><mi>K</mi><mo>×</mo><mn>0.005</mn><mo>=</mo><mn>150</mn><mtext>connections concurrent</mtext></mrow><annotation encoding="application/x-tex">L = 30K × 0.005 = 150 \\text{connections concurrent} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">30</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0.005</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mord">150</span><span class="mord text"><span class="mord">connections concurrent</span></span></span></span></span></span></p><p>设 NB PG max=100, queue 50 等待 ⇒ W 边界 queue add ≈ queuing delay 即 50/30K = 1.7ms; 这是 backpressure. DBA set pool=200 → connection far exceeds max=100 throughput cap → connection refused. Pool=150 是 sweet spot.</p><p><strong>经验公式</strong>: pool size = avg_request_time × peak_qps (Little&#39;s law) <strong>+ safety headroom 20%</strong>, 网络 spare capacity.</p><h3 id="例-3-api-gateway-rate-limit" tabindex="-1">例 3: API Gateway Rate Limit <a class="header-anchor" href="#例-3-api-gateway-rate-limit" aria-label="Permalink to &quot;例 3: API Gateway Rate Limit&quot;">​</a></h3><p>Token bucket 风格 rate limit:</p><ul><li>100 RPS token refill</li><li>each request consumes 1 token</li><li>burst 5 token initial bucket</li></ul><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>L</mi><mrow><mi>t</mi><mi>o</mi><mi>k</mi><mi>e</mi><mi>n</mi><mi>s</mi></mrow></msub><mo>=</mo><mi>r</mi><mi>e</mi><mi>f</mi><mi>i</mi><mi>l</mi><mi>l</mi><mo>×</mo><mi>b</mi><mi>u</mi><mi>r</mi><mi>s</mi><mi>t</mi><mi>r</mi><mi>e</mi><mi>f</mi><mi>i</mi><mi>l</mi><mi>l</mi><mi>p</mi><mi>e</mi><mi>r</mi><mi>i</mi><mi>o</mi><mi>d</mi></mrow><annotation encoding="application/x-tex">L_{tokens} = refill × burst refill period </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal">i</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">u</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">s</span><span class="mord mathnormal">t</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal">i</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">p</span><span class="mord mathnormal" style="margin-right:0.0278em;">er</span><span class="mord mathnormal">i</span><span class="mord mathnormal">o</span><span class="mord mathnormal">d</span></span></span></span></span></p><p>通常 Little&#39;s Law 应用于&quot;waiting queue&quot;:</p><ul><li>到达 λ=200/s, 服务 μ=100/s ⇒ unstable ⇒ L → ∞</li><li>必须配 <code>Bounded Queue with Backpressure</code> (限流器)</li></ul><h3 id="例-4-queue-talk-code" tabindex="-1">例 4: Queue, Talk Code <a class="header-anchor" href="#例-4-queue-talk-code" aria-label="Permalink to &quot;例 4: Queue, Talk Code&quot;">​</a></h3><p>Kafka topic 承接 1M events/s produce rate, consumer 处理 0.2M/s → consumer lag:</p><ul><li>L_lag = (λ_producer - λ_consumer) × time</li><li>1 hour lag = 1M-0.2M = 0.8M × 3600 = 2.88B events.</li></ul><p>→ 必须加消费者 (subscribing 同 group). 9 more consumers × 0.2M/s each = 1.8M/s consume, lag decreases.</p><h3 id="例-5-pinning-worker-pool-for-cron-tasks" tabindex="-1">例 5: Pinning worker pool for cron tasks <a class="header-anchor" href="#例-5-pinning-worker-pool-for-cron-tasks" aria-label="Permalink to &quot;例 5: Pinning worker pool for cron tasks&quot;">​</a></h3><p>K8s 集群 running 1000 concurrently active CronJobs, 平均 job runs 5min:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mi>e</mi><mi>x</mi><mi>p</mi><mi>e</mi><mi>c</mi><mi>t</mi><mi>e</mi><mi>d</mi><mi mathvariant="normal">_</mi><mi>a</mi><mi>r</mi><mi>r</mi><mi>i</mi><mi>v</mi><mi>a</mi><mi>l</mi><mo>×</mo><mi>W</mi><mo>=</mo><mi>h</mi><mi>o</mi><mi>w</mi><mi>m</mi><mi>a</mi><mi>n</mi><mi>y</mi><mi>C</mi><mi>r</mi><mi>o</mi><mi>n</mi><mi>J</mi><mi>o</mi><mi>b</mi><mi>s</mi><mi mathvariant="normal">/</mi><mi>s</mi><mi>e</mi><mi>c</mi><mo>×</mo><mn>300</mn><mi>s</mi><mi>e</mi><mi>c</mi></mrow><annotation encoding="application/x-tex">L = expected \\_arrival × W = how many CronJobs/sec × 300 sec </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.0044em;vertical-align:-0.31em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal">x</span><span class="mord mathnormal">p</span><span class="mord mathnormal">ec</span><span class="mord mathnormal">t</span><span class="mord mathnormal">e</span><span class="mord mathnormal">d</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">i</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">h</span><span class="mord mathnormal">o</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal">man</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">o</span><span class="mord mathnormal">n</span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mord mathnormal">o</span><span class="mord mathnormal">b</span><span class="mord mathnormal">s</span><span class="mord">/</span><span class="mord mathnormal">sec</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">300</span><span class="mord mathnormal">sec</span></span></span></span></span></p><p>若 scheduled frequency 总和 10/sec入 enqueued:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mn>10</mn><mo>×</mo><mn>300</mn><mo>=</mo><mn>3000</mn><mtext> concurrent Pods</mtext></mrow><annotation encoding="application/x-tex">L = 10 × 300 = 3000 \\text{ concurrent Pods} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">300</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">3000</span><span class="mord text"><span class="mord"> concurrent Pods</span></span></span></span></span></span></p><h3 id="例-6-cache-capacity-planning" tabindex="-1">例 6: Cache capacity planning <a class="header-anchor" href="#例-6-cache-capacity-planning" aria-label="Permalink to &quot;例 6: Cache capacity planning&quot;">​</a></h3><p>Redis cache:</p><ul><li>到达: 100K QPS read calls.</li><li>平均响应时间: 0.5ms (sub-ms cache hit).</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>=</mo><mn>100</mn><mi>K</mi><mo>×</mo><mn>0.0005</mn><mo>=</mo><mn>50</mn></mrow><annotation encoding="application/x-tex">L = 100K × 0.0005 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">100</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0.0005</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> concurrent connections.</li><li>Redis pipelining: 1 connection handles 50 ops (pipeline batch) → reduce to 1 concurrent connection (per worker thread pool).</li></ul><h3 id="例-7-connection-static-关闭-delay-reverse" tabindex="-1">例 7: Connection static: 关闭 delay reverse <a class="header-anchor" href="#例-7-connection-static-关闭-delay-reverse" aria-label="Permalink to &quot;例 7: Connection static: 关闭 delay reverse&quot;">​</a></h3><p>Server 5K QPS with persistent HTTP/2 connection work from clients:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mn>5</mn><mi>K</mi><mo>×</mo><mi>W</mi><mo>=</mo><mn>5</mn><mi>K</mi><mo>×</mo><mn>1</mn><mi>s</mi><mo stretchy="false">(</mo><mi>k</mi><mi>e</mi><mi>e</mi><mi>p</mi><mo>−</mo><mi>a</mi><mi>l</mi><mi>i</mi><mi>v</mi><mi>e</mi><mi>d</mi><mi>e</mi><mi>f</mi><mi>a</mi><mi>u</mi><mi>l</mi><mi>t</mi><mo stretchy="false">)</mo><mo>=</mo><mn>5</mn><mi>K</mi><mi>o</mi><mi>p</mi><mi>e</mi><mi>n</mi><mi>c</mi><mi>o</mi><mi>n</mi><mi>n</mi><mi>e</mi><mi>c</mi><mi>t</mi><mi>i</mi><mi>o</mi><mi>n</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">L = 5K × W = 5K × 1s (keep-alive default) = 5K open connections </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mord mathnormal">ee</span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">i</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mord mathnormal">e</span><span class="mord mathnormal">d</span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal">a</span><span class="mord mathnormal">u</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">5</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal">o</span><span class="mord mathnormal">p</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mord mathnormal">co</span><span class="mord mathnormal">nn</span><span class="mord mathnormal">ec</span><span class="mord mathnormal">t</span><span class="mord mathnormal">i</span><span class="mord mathnormal">o</span><span class="mord mathnormal">n</span><span class="mord mathnormal">s</span></span></span></span></span></p><p>must bump fd-max limit to 65535.</p><h3 id="例-8-storage-write-throughput" tabindex="-1">例 8: Storage Write Throughput <a class="header-anchor" href="#例-8-storage-write-throughput" aria-label="Permalink to &quot;例 8: Storage Write Throughput&quot;">​</a></h3><p>PostgreSQL 1MB writes 要 1ms (fsync bound).</p><p>100MB/s write rate = 100 concurrent 1MB writes in flight = 100 fsyncs concurrent → but fsync 1ms 串行化 → actually max 1000 fsync/sec → max ~1MB × 1000 = 1GB/s.</p><p>反推 bound:</p><ul><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>W</mi><mrow><mi>f</mi><mi>s</mi><mi>y</mi><mi>n</mi><mi>c</mi></mrow></msub><mo>=</mo><mn>1</mn><mi>m</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">W_{fsync} = 1ms</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">sy</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mord mathnormal">m</span><span class="mord mathnormal">s</span></span></span></span></li><li>服务率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi><mo>=</mo><mn>1000</mn><mi mathvariant="normal">/</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">μ = 1000/s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1000/</span><span class="mord mathnormal">s</span></span></span></span></li><li>arrived <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>=</mo><mn>50</mn><mi>K</mi><mi mathvariant="normal">/</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">λ = 50K/s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">50</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord">/</span><span class="mord mathnormal">s</span></span></span></span> if each is a 1KB write batched 50K → unstable.</li><li>batched to 1ms 一 fsync with 100 batched writes per fsync → effective λ=500/s sat at μ. Sweet spot is batched with <code>synchronous_commit=off</code> + <code>wal_writer_delay=10ms</code> aggregation.</li></ul><hr><h2 id="三、counter-examples-little-s-law-失效情形" tabindex="-1">三、Counter-Examples: Little&#39;s Law 失效情形 <a class="header-anchor" href="#三、counter-examples-little-s-law-失效情形" aria-label="Permalink to &quot;三、Counter-Examples: Little&#39;s Law 失效情形&quot;">​</a></h2><h3 id="不-稳态" tabindex="-1">不 稳态 <a class="header-anchor" href="#不-稳态" aria-label="Permalink to &quot;不 稳态&quot;">​</a></h3><p>队列只在 λ&lt;μ (稳定条件)才 stable. λ&gt;μ ⇒ 无限增长, Little&#39;s Law 仍可用 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>=</mo><mi>L</mi><mo stretchy="false">(</mo><mn>0</mn><mo stretchy="false">)</mo><mo>+</mo><mi>λ</mi><mi>t</mi><mo>−</mo><mi>μ</mi><mi>t</mi></mrow><annotation encoding="application/x-tex">L = L(0) + λt - μt</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">L</span><span class="mopen">(</span><span class="mord">0</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">λ</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8095em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mord mathnormal">t</span></span></span></span> for transient (t时间), 但 steady-state 极限定理不成立. industrial example: 流量激增引发 backpressure.</p><h3 id="突发-vs-平均" tabindex="-1">突发 vs 平均 <a class="header-anchor" href="#突发-vs-平均" aria-label="Permalink to &quot;突发 vs 平均&quot;">​</a></h3><p>平均 λ=10/s但 突发 100/s for 1 second:</p><ul><li>Little&#39;s Law 用平均算 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>=</mo><mn>10</mn><mo>×</mo><mi>W</mi></mrow><annotation encoding="application/x-tex">L=10×W</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span></span></span></span>, 但 burst 期间 W trajectory 可能短暂超 stable W 估计 → P99 latency 实际 spiking. 平均不制约P99 致命.</li></ul><p>修: bursty service 自配超额 worker 处理 burst. 类似 batch 可以 concurrent 突发的 100+ tasks.</p><h3 id="priority-queue-不-道" tabindex="-1">Priority Queue 不 道 <a class="header-anchor" href="#priority-queue-不-道" aria-label="Permalink to &quot;Priority Queue 不 道&quot;">​</a></h3><p>Priority queue 可能 starve 低 priority. λ&lt;=μ 总稳态, 但低 priority class 的 effective μ→ 0, 它的 W → ∞. Little&#39;s Law 仍适用 per class — one for low priority stretch.</p><h3 id="state-dependent-服务率" tabindex="-1">State-Dependent 服务率 <a class="header-anchor" href="#state-dependent-服务率" aria-label="Permalink to &quot;State-Dependent 服务率&quot;">​</a></h3><p>服务率 μ dependent on system state (state-aware 算数据 增 mark)(和一个 load shedding 算法): <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi><mo mathvariant="normal">≠</mo></mrow><annotation encoding="application/x-tex">\\mu \\ne</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord katex-vbox"><span class="katex-thinbox"><span class="rlap"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="katex-inner"><span class="mord"><span class="mrel"></span></span></span><span class="katex-fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span></span></span></span> const. Little&#39;s Law 只算 stable expected average λ &amp; W, 不描述 transient + state dependent dynamics.</p><h3 id="closed-loop-network" tabindex="-1">Closed Loop (Network) <a class="header-anchor" href="#closed-loop-network" aria-label="Permalink to &quot;Closed Loop (Network)&quot;">​</a></h3><p>用户 reply-driven retry 给系统再加 load (closed-loop), 客户端 λ 实际interface-dependent on observed latency (e.g., if server slow, user lowers its issue rate, &quot;throttling&quot;). Little&#39;s Law formula still works in expectation, but λ self-feedback depends on W ⇒ not externally regulated model.</p><p>类似 example: HTTP client with finite pool (50 connection threads); individual request thread blocks ⇒ users don&#39;t issue new ones until release ⇒ instantaneous λ dynamically bounded.</p><hr><h2 id="四、little-s-law-边界应用" tabindex="-1">四、Little&#39;s Law 边界应用 <a class="header-anchor" href="#四、little-s-law-边界应用" aria-label="Permalink to &quot;四、Little&#39;s Law 边界应用&quot;">​</a></h2><h3 id="queueing-theory-推论-kingman-公式" tabindex="-1">Queueing Theory 推论 Kingman 公式 <a class="header-anchor" href="#queueing-theory-推论-kingman-公式" aria-label="Permalink to &quot;Queueing Theory 推论 Kingman 公式&quot;">​</a></h3><p>单 server M/M/1 queue:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>W</mi><mrow><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi></mrow></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mi>μ</mi><mo>−</mo><mi>λ</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">W_{total} = \\frac{1}{\\mu - \\lambda} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.2019em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">λ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>即 delay explodes 1/(μ-λ) when arrival → capacity. P99 latency 公式 (金海 method):</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>W</mi><mrow><mi>P</mi><mn>99</mn></mrow></msub><mo>≈</mo><mfrac><mrow><mi>l</mi><mi>n</mi><mo stretchy="false">(</mo><mn>100</mn><mo stretchy="false">)</mo></mrow><mrow><mi>μ</mi><mo>−</mo><mi>λ</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">W_{P99} \\approx \\frac{ln(100)}{\\mu - \\lambda} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="mord mtight">99</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.3074em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">λ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">n</span><span class="mopen">(</span><span class="mord">100</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>→ 1% overload → P99 latency 4.6× mean.</p><p>应用: never run server at λ/μ &gt; ~80%. Always leave μ 20% headroom. P99 latency is very sensitive to saturation point.</p><h3 id="universal-scalability-law-usl-neil-gunther" tabindex="-1">Universal Scalability Law (USL, Neil Gunther) <a class="header-anchor" href="#universal-scalability-law-usl-neil-gunther" aria-label="Permalink to &quot;Universal Scalability Law (USL, Neil Gunther)&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>X</mi><mo stretchy="false">(</mo><mi>N</mi><mo stretchy="false">)</mo><mo>=</mo><mfrac><mrow><mi>λ</mi><mi>N</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>α</mi><mo stretchy="false">(</mo><mi>N</mi><mo>−</mo><mn>1</mn><mo stretchy="false">)</mo><mo>+</mo><mi>β</mi><mi>N</mi><mo stretchy="false">(</mo><mi>N</mi><mo>−</mo><mn>1</mn><mo stretchy="false">)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">X(N) = \\frac{λ N}{1 + α(N-1) + β N(N-1)} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.3074em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><ul><li>N = 并发数</li><li>α = contention cost (锁竞争, 锁开销)</li><li>β = coherency cost (consensus coordination)</li></ul><p>β=0 (no coherency): Amdahl scaling. With coherency increasing, throughput 比 retrograde past N*.</p><p>USL 是 Little&#39;s Law 的 capacity scaling 推广, 用于 capacity planning 实际 SRE work.</p><hr><h2 id="五、工业-best-practice" tabindex="-1">五、工业 Best Practice <a class="header-anchor" href="#五、工业-best-practice" aria-label="Permalink to &quot;五、工业 Best Practice&quot;">​</a></h2><h3 id="pool-sizing-公式" tabindex="-1">Pool Sizing 公式 <a class="header-anchor" href="#pool-sizing-公式" aria-label="Permalink to &quot;Pool Sizing 公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pool_size = peak_QPS × avg_response_time_seconds × safety_factor</span></span></code></pre></div><p>where <code>peak_QPS</code> is 业务 peak (考虑 5-10× diurnal 突发); <code>avg_response_time_seconds</code> 实测含 cache miss P50; <code>safety_factor = 1.2 - 1.5</code>.</p><h3 id="connection-pool-cap" tabindex="-1">Connection Pool Cap <a class="header-anchor" href="#connection-pool-cap" aria-label="Permalink to &quot;Connection Pool Cap&quot;">​</a></h3><p>PostgreSQL / MySQL connection pool max:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>p</mi><mi>o</mi><mi>o</mi><msub><mi>l</mi><mrow><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>m</mi><mi>a</mi><mi>x</mi><mo stretchy="false">(</mo><mi>T</mi><mi>P</mi><mi>D</mi><mi>B</mi><mi mathvariant="normal">_</mi><mi>t</mi><mi>p</mi><mi>s</mi><mo stretchy="false">)</mo></mrow><mrow><mi>Q</mi><mi>P</mi><mi>S</mi><mi mathvariant="normal">_</mi><mi>p</mi><mi>e</mi><mi>r</mi><mi mathvariant="normal">_</mi><mi>p</mi><mi>o</mi><mi>o</mi><mi>l</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">pool_{max} = \\frac{max(TPDB\\_tps)}{QPS\\_per\\_pool} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mord mathnormal">oo</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.446em;vertical-align:-0.996em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.45em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">QP</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">p</span><span class="mord mathnormal" style="margin-right:0.0278em;">er</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">p</span><span class="mord mathnormal">oo</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.7em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">ma</span><span class="mord mathnormal">x</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">tp</span><span class="mord mathnormal">s</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.996em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>但是 DB max connections 实际受 shared_buffers RAM; 100 connection 20MB each = 2GB shared buffer. Diminishing returns 在 connection &gt;50.</p><h3 id="k8s-hpa-based-on-queue-depth" tabindex="-1">K8s HPA Based on Queue Depth <a class="header-anchor" href="#k8s-hpa-based-on-queue-depth" aria-label="Permalink to &quot;K8s HPA Based on Queue Depth&quot;">​</a></h3><p>HPA scaling on Kafka consumer <code>queuelag</code> 比 CPU 利用率更精确——stability 与 queue depth 显著关系. <code>Sharded Queue Lag = lag/consumers/60</code> → if lag/consumer &gt; 60s需要加消费者.</p><h3 id="slo-with-little-s-law" tabindex="-1">SLO with Little&#39;s Law <a class="header-anchor" href="#slo-with-little-s-law" aria-label="Permalink to &quot;SLO with Little&#39;s Law&quot;">​</a></h3><p>SRE SLO: target availability 99.9% = 8.6 sec/min deficit budget.</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>b</mi><mi>u</mi><mi>d</mi><mi>g</mi><mi>e</mi><mi>t</mi><mo>=</mo><mo stretchy="false">(</mo><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi><mi mathvariant="normal">_</mi><mi>t</mi><mi>i</mi><mi>m</mi><mi>e</mi><mo stretchy="false">)</mo><mo>×</mo><mo stretchy="false">(</mo><mn>1</mn><mo>−</mo><mi>S</mi><mi>L</mi><mi>I</mi><mi mathvariant="normal">_</mi><mrow><mi>t</mi><mi>a</mi><mi>r</mi><mi>g</mi><mi>e</mi><mi>t</mi></mrow><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">budget = (total \\_time) × (1 - SLI\\_{target}) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">u</span><span class="mord mathnormal">d</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord mathnormal">e</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mord mathnormal">o</span><span class="mord mathnormal">t</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">t</span><span class="mord mathnormal">im</span><span class="mord mathnormal">e</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal">L</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord"><span class="mord mathnormal">t</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord mathnormal">e</span><span class="mord mathnormal">t</span></span><span class="mclose">)</span></span></span></span></span></p><p>Throughput stable under nominal arrival rate. SLO violation triggers autoscale/degrade.</p><hr><h2 id="六、典型事故" tabindex="-1">六、典型事故 <a class="header-anchor" href="#六、典型事故" aria-label="Permalink to &quot;六、典型事故&quot;">​</a></h2><h3 id="netflix-spotinstance-queue-backlog-2009" tabindex="-1">Netflix SpotInstance Queue Backlog 2009 <a class="header-anchor" href="#netflix-spotinstance-queue-backlog-2009" aria-label="Permalink to &quot;Netflix SpotInstance Queue Backlog 2009&quot;">​</a></h3><p>某 auto-scaling based on CPU fanout: λ=N req/s consumers consume once CPU done; but CPU 相 throughput saturated → lag grows → Little&#39;s Law predicts sustained queue grows linearly. Fix: HPA metric on queue depth (Kafka consumer <code>lag</code>).</p><h3 id="twitter-kestrel-queue-transient-stack-2011" tabindex="-1">Twitter Kestrel Queue Transient Stack 2011 <a class="header-anchor" href="#twitter-kestrel-queue-transient-stack-2011" aria-label="Permalink to &quot;Twitter Kestrel Queue Transient Stack 2011&quot;">​</a></h3><p>Kestrel原始的 Little&#39;s Law not fully digestible — burst λ not stable. Queue overflow caused OOM. Fix: strict bounded queue + immediate backpressure to producer (Twitter internal Scala).</p><h3 id="slack-2019-connection-drops" tabindex="-1">Slack 2019 connection drops <a class="header-anchor" href="#slack-2019-connection-drops" aria-label="Permalink to &quot;Slack 2019 connection drops&quot;">​</a></h3><p>Slack WebSocket connection pool capped at 10K, 然而 Little&#39;s Law pred L=20K concurrent stable state. Result: dropped 5K connections every 5min. Fix: bump Linux ulimit + net.core.somaxconn, deploy larger泓 worker pool.</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>Little&#39;s Law 是 stable state</strong>: λ&lt;μ req&#39;d. λ&gt;=μ → unbounded growth, 公式 temporarily得不到 pull L 不 steady.</li><li><strong>顿 mean time vs Juan99</strong>: Little&#39;s Law 只 defend 平均; P99 的 interp 通过 Kingman formula 的人际必借extra.</li><li><strong>Connection pool 大不总好</strong>: DB max_connections 制限 RAM, 每 connection消耗 ~5-20MB. Postgres 最多 推荐几一百, 超过风险 OOM.</li><li><strong>Thread pool sizing必算 cache hit ratio</strong>: cache miss 让 W 增大⇒ L 增大, 现在 pool 突然over-subscription。 测试 службу best worst-case scenario。</li><li><strong>Backpressure based on queue depth 不是 CPU</strong>: queue depth 是 lateness (queue内等待时间) directly → better autoscale signal.</li><li><strong>Burst arrival 能 找 transient overload</strong>: λ average 1×10/s, but 1秒内 1000 réqs; 服务者正有效 only stable at slow rate ⇒ 1秒内设 queue 暴发 → transient P99 bad.</li><li><strong>Rate limiters 不 是 little&#39;s law in themselves</strong>: token bucket 是幼儿建立 model on variation of μ, 上 limit λ to &lt;= 50%. SaaS rate limit 关系 setting the μ - λ 整 stability rules.</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>Little&#39;s Law <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>=</mo><mi>λ</mi><mo>×</mo><mi>W</mi></mrow><annotation encoding="application/x-tex">L = \\lambda \\times W</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span></span></span></span> 是 stable system 的稳态不变量, 适用于生死意毛任何queue with stable regime.</li><li>工业 best practice: pool size = peak QPS × avg响应 时 × 安全 factor(1.2-1.5).</li><li>不能 oversubscribe μ: 必须 leave 20% 容量 headroom以避免 P99 latency blow up.</li><li>Kingman formula: 单 server M/M/1 queue <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>W</mi><mo>=</mo><mn>1</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mi>μ</mi><mo>−</mo><mi>λ</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">W = 1/(\\mu-\\lambda)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mopen">(</span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mclose">)</span></span></span></span>, P99 latency <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi>W</mi><mo>×</mo><mi>l</mi><mi>n</mi><mo stretchy="false">(</mo><mn>100</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">≈ W × ln(100)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">n</span><span class="mopen">(</span><span class="mord">100</span><span class="mclose">)</span></span></span></span>. α=0.95 → latency 20× backof 2.9. ring.</li><li>Universal Scalability Law 购机 capacity scaling, Better than Amdahl, 包含 coherency term β for cluster contention.</li><li><strong>Coherency cost</strong> increases quadratically with N, which is 是 why shared read-only cache 离线 nodes can use simple sharding 不 rehashable.</li></ol><hr><p>下一节 → <a href="./load-patterns">负载模式</a></p>',116)])])}const d=s(m,[["render",l]]);export{g as __pageData,d as default};
